<?php
require_once dirname(__DIR__).'/includes/functions.php';require_content_manager();verify_csrf();$id=(int)($_POST['application_id']??0);
$s=$con->prepare("SELECT a.user_id,j.title,j.description,j.requirements,j.career_id FROM job_applications a JOIN job_opportunities j ON j.id=a.job_id WHERE a.id=?");$s->bind_param('i',$id);$s->execute();$a=$s->get_result()->fetch_assoc();if(!$a)json_response(['ok'=>false,'message'=>'Application not found.'],404);
$s=$con->prepare('SELECT qualification,field_of_study,is_current FROM user_education WHERE user_id=? ORDER BY is_current DESC,end_year DESC');$s->bind_param('i',$a['user_id']);$s->execute();$education=[];foreach($s->get_result() as $x)$education[]=$x['qualification'].($x['field_of_study']?' in '.$x['field_of_study']:'').($x['is_current']?' (in progress)':'');
$career=(int)$a['career_id'];$s=$con->prepare("SELECT q.title,COUNT(qa.id) attempts,MAX(ROUND(qa.score/NULLIF(qa.max_score,0)*100)) best_score,MAX(qa.passed) passed FROM quizzes q JOIN quiz_attempts qa ON qa.quiz_id=q.id AND qa.user_id=? WHERE (?=0 OR q.career_id=?) GROUP BY q.id,q.title");$s->bind_param('iii',$a['user_id'],$career,$career);$s->execute();$performance=[];foreach($s->get_result() as $q)$performance[]=$q['title'].': '.(int)$q['best_score'].'% best, '.($q['passed']?'passed':'not passed').', '.$q['attempts'].' attempts';
$context="Job: {$a['title']}\nDescription: {$a['description']}\nRequirements: {$a['requirements']}\nEducation: ".($education?implode('; ',$education):'No records')."\nRelevant quiz evidence: ".($performance?implode('; ',$performance):'No attempts')."\nA resume is attached, but its contents are not provided.";
$reply=groq_chat([['role'=>'system','content'=>'Assist a human job-application reviewer using only supplied evidence. Do not make a hiring decision, infer sensitive traits, or treat missing evidence as inability. Return JSON only: {"summary":"2-3 neutral sentences","strengths":["..."],"gaps":["..."],"interview_questions":["..."]}. Give 2-4 concise items per list.'],['role'=>'user','content'=>$context]],['json'=>true,'max_tokens'=>900,'timeout'=>25]);if($reply===null)json_response(['ok'=>false,'message'=>'AI is temporarily unavailable. Please try again later.'],503);$analysis=json_decode($reply,true);if(!is_array($analysis)||empty($analysis['summary'])||!is_array($analysis['strengths']??null)||!is_array($analysis['gaps']??null)||!is_array($analysis['interview_questions']??null)){error_log('[CareerSim Groq] Invalid application analysis JSON');json_response(['ok'=>false,'message'=>'AI is temporarily unavailable. Please try again later.'],503);}json_response(['ok'=>true,'analysis'=>$analysis]);
